import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'rel': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters, row = m.group(1), int(m.group(2))
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx - 1, row - 1  # 0-based col, 0-based row

path = 'budget.xlsx'
with zipfile.ZipFile(path) as z:
    print("ZIP entries:")
    for n in z.namelist():
        print("  ", n)

    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for s in wb.find('main:sheets', NS):
        sheets.append((s.get('name'), s.get('sheetId'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
    print("\nSheets:", sheets)

    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for r in rels:
        rel_map[r.get('Id')] = r.get('Target')
    print("Rels:", rel_map)

    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss.findall('main:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    for name, sid, rid in sheets:
        target = rel_map.get(rid)
        if target.startswith('/'):
            target = target[1:]
        else:
            target = 'xl/' + target.lstrip('/')
        print(f"\n--- Sheet '{name}' -> {target} ---")
        root = ET.fromstring(z.read(target))
        data = root.find('main:sheetData', NS)
        rows = []
        for row_el in data.findall('main:row', NS):
            cells = {}
            for c in row_el.findall('main:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('main:v', NS)
                val = v.text if v is not None else ''
                if t == 's':
                    val = shared[int(val)]
                elif t == 'inlineStr':
                    isel = c.find('main:is', NS)
                    val = ''.join(tt.text or '' for tt in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')) if isel is not None else ''
                elif t == 'b':
                    val = val == '1'
                col, row = col_to_idx(ref)
                cells[col] = val
            if cells:
                rows.append((row_el.get('r'), cells))
        for rnum, cells in rows:
            for col in sorted(cells):
                print(f"  R{rnum} C{col+1}: {cells[col]!r}")

import sys, shutil, subprocess, os, site

print("python:", sys.version)
print("executable:", sys.executable)
for p in sys.path:
    print("path:", p)

soffice = shutil.which("soffice") or shutil.which("libreoffice")
print("soffice:", soffice)

for base in [site.getsitepackages(), [site.getusersitepackages()]]:
    pass
sp = list(site.getsitepackages()) + [site.getusersitepackages()]
for d in sp:
    if d and os.path.isdir(d):
        hits = [n for n in os.listdir(d) if "openpyxl" in n.lower() or "pandas" in n.lower()]
        if hits:
            print("site-package hits in", d, ":", hits)

try:
    r = subprocess.run(["soffice", "--version"], capture_output=True, text=True, timeout=15)
    print("soffice --version rc:", r.returncode, "out:", r.stdout.strip(), "err:", r.stderr.strip())
except Exception as e:
    print("soffice --version failed:", e)

